@import "tailwindcss";
@import "./styles/ui.css";
@import "@fontsource-variable/geist/wght.css";


/*
 * Bot Company motion tokens; keep in sync with src/lib/motion.ts. --ease-exit is the exact
 * time-reverse of --ease-enter, so an exit replays its enter backwards; --ease-standard
 * mirrors itself, for two-way CSS state changes (hover, focus).
 */
:root {
  --motion-fast: 150ms;
  --motion-base: 220ms;
  --motion-slow: 300ms;
  --ease-enter: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.64, 0, 0.78, 0);
  --ease-standard: cubic-bezier(0.45, 0, 0.55, 1);
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
}

.rk-scroll::-webkit-scrollbar {
  width: 6px;
}
.rk-scroll {
  scrollbar-color: var(--scrollbar) transparent;
  scrollbar-width: thin;
}
.rk-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.rk-scroll::-webkit-scrollbar-thumb {
  background: var(--scrollbar);
  border-radius: 3px;
}
.rk-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-hover);
}

.app-drag {
  -webkit-app-region: drag;
  user-select: none;
}

.app-no-drag {
  -webkit-app-region: no-drag;
}

@keyframes rkPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}
